-- Study Abroad country content, BATCH 20: Ecuador, Cuba, Jamaica, Moldova, Trinidad and Tobago.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('ecuador', 'cuba', 'jamaica', 'moldova', 'trinidad-and-tobago'));
UPDATE countries SET why_title = 'Why study in Ecuador?', why_body = '<p>Ecuador combines the Andes, the Amazon and the Galápagos with low costs and growing universities such as Universidad San Francisco de Quito, strong in environment, biology and Spanish language.</p><ul><li>Biodiversity and environmental research (including the Galápagos)</li><li>Low costs compared with North America and Europe</li><li>Spanish immersion</li><li>Strong liberal arts and sciences at private universities</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>A degree needs a <strong>temporary residence visa for students</strong>, applied for online on the e-VISAS platform. One guide reports fees of US$50 to apply and US$80 when granted (2026); another lists US$100 and 3-8 weeks, so confirm with the ministry.</p><ul><li>Admission letter from a recognised Ecuadorian institution</li><li>Proof of funds: income of at least one basic unified salary (SBU) a month, parental support for students up to 21, or a scholarship letter (Ministerial Agreement 70 of 2024)</li><li>Passport, photographs and criminal record certificate</li><li>The 180-day threshold in an older USFQ document differs from the 90 days in other sources; confirm</li><li>The visa reportedly covers internships; check work rules with the foreign ministry</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ecuador Ministry of Foreign Affairs (cancilleria.gob.ec) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Spanish language proof for Spanish-taught programmes</li><li>Entrance exam at some universities</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No USFQ tuition figures were found.</p><ul><li>Check each university schedule; private universities set their own fees</li><li>No national scholarship programme for foreign degree students on the official pages checked</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate, apostilled</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'ecuador';
UPDATE countries SET why_title = 'Why study in Cuba?', why_body = '<p>Cuba is known for free medical education at the Latin American School of Medicine (ELAM) and strong programmes in medicine, biotechnology and the arts. Conditions in 2026 are difficult, so check carefully.</p><ul><li>ELAM tuition, room and board are described as free for eligible students</li><li>Strong in medicine, biotechnology and the arts</li><li>Spanish immersion</li><li>Distinct culture and history</li></ul><p>Check your government''s current travel advice before planning to study here.</p>', visa_title = 'Student visa requirements', visa_body = '<p>Your Cuban institution must first contact the immigration office in Cuba; the consulate does not issue the visa without that authorisation. Consular fees were updated on 1 October 2026, so ask the consulate for the current amount.</p><ul><li>Admission or scholarship letter from a Cuban institution</li><li>Passport and photographs</li><li>Authorisation from Cuban immigration obtained by the institution</li><li>As of 18 October 2026 the UK FCDO advises against all but essential travel to Cuba</li><li>International Visa and Mastercard cards are reported as not accepted and cannot be used at ATMs</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Cuban consulate and your institution site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>ELAM places usually come through government scholarship offers made to partner countries, such as the 2026-27 Cuba scholarship announced by the Maldives government.</p><ul><li>Academic transcripts and certificates</li><li>Spanish language preparation</li><li>Entrance requirements per programme</li><li>Medical certificate</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Most sources describe ELAM tuition as free, with room and board and a small stipend; uniRank lists tuition as "not reported".</p><ul><li>ELAM: free tuition, room and board for scholarship students (reported)</li><li>Your main cost is travel to and from Cuba</li><li>Teaching was announced as mainly blended and distance learning from 20 August 2026 because of fuel shortages (reported)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official institution site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes; Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'cuba';
UPDATE countries SET why_title = 'Why study in Jamaica?', why_body = '<p>Jamaica is home to the Mona campus of the University of the West Indies and other institutions, offering English-medium degrees in medicine, law, business, media and sciences.</p><ul><li>English-medium teaching</li><li>UWI Mona is a leading Caribbean university</li><li>Strong in medicine, law, media and the arts</li><li>Caribbean culture and music</li></ul>', visa_title = 'Student status requirements', visa_body = '<p>Students from outside CARICOM who need a visa get one from a Jamaican mission, which acts as a landing permit. Students then get <strong>student status</strong> as an extension of stay from PICA. Sources disagree on whether there is a separate student visa, so check with your mission.</p><ul><li>Admission letter from a Jamaican institution</li><li>Extension of stay within 2 weeks of arrival, reported at JMD 10,000 (2026)</li><li>No official proof-of-funds figure is published</li><li>A student extension does not allow work; employment needs a work permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Jamaican mission, PICA and the UWI International Students Office site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution.</p><ul><li>Academic transcripts and certificates</li><li>CSEC/CAPE or equivalent qualifications, or A-levels</li><li>English proficiency proof for non-native speakers</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Official UWI Mona fee schedules found were for 2025-26.</p><ul><li>A third-party guide reports for 2026-27: most full-time undergraduate programmes at about US$15,000 a year, and MBBS and dentistry at about US$28,000</li><li>UCC estimates living costs at about US$3,000-$5,000 a year beyond tuition</li><li>Check the official UWI Mona fee schedule for current figures</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> CSEC/CAPE or an equivalent with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'jamaica';
UPDATE countries SET why_title = 'Why study in Moldova?', why_body = '<p>Moldova offers low-cost, English- and Romanian-taught degrees, especially medicine at Nicolae Testemitanu State University of Medicine and Pharmacy, in a small and affordable European country.</p><ul><li>English-taught medicine and dentistry</li><li>Low tuition and living costs</li><li>Romanian-language links to the EU</li><li>Easy entry for many nationalities</li></ul>', visa_title = 'Visa and residence permit', visa_body = '<p>Citizens of visa-free countries do not need a visa to enter for study. Others need a <strong>long-stay student visa (Type D/BS)</strong> and a residence permit after arrival.</p><ul><li>Admission letter and valid passport</li><li>Rental contract or proof of property ownership for housing</li><li>Criminal record certificate valid on entry</li><li>Temporary residence permit within 30 days of arrival (IGM); Testemitanu says report within 3 days, so confirm</li><li>Optional medical insurance of at least 3 months in year one; mandatory insurance afterwards</li><li>Students on Moldovan government scholarships do not need to prove funds</li><li>Part-time work of up to 20 hours a week reported</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official IGM (igm.gov.md) and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, and the national Study in Moldova portal lists the process.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English or Romanian language proof</li><li>Entrance exam for medicine in biology and chemistry</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No Testemitanu tuition figures were found.</p><ul><li>Check each university; medicine is usually the highest fee</li><li>Living costs: about €300-€600 a month (estimate)</li><li>Health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or Romanian proof depending on the programme</li></ul>' WHERE slug = 'moldova';
UPDATE countries SET why_title = 'Why study in Trinidad and Tobago?', why_body = '<p>Trinidad and Tobago hosts the St. Augustine campus of the University of the West Indies, with strong programmes in engineering, medicine, energy and agriculture, and a lively Caribbean culture.</p><ul><li>UWI St. Augustine as a leading regional university</li><li>Strong in energy, engineering and agriculture</li><li>English-medium teaching</li><li>Carnival and Caribbean culture</li></ul>', visa_title = 'Student permit requirements', visa_body = '<p>Registered full-time UWI St. Augustine students do not need a student permit, although a visa may be required depending on nationality. Students at other institutions apply online for a permit through the eStudentPermit portal.</p><ul><li>Passport valid for at least 1 year and a digital passport photo</li><li>Permit fee reported at TT$400 for non-CARICOM and TT$200 for CARICOM nationals (non-refundable)</li><li>Any non-national working for more than 30 days needs a work permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official T&T Immigration Division and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>UWI St. Augustine undergraduate applications run online from mid-November to the end of May, with a non-refundable US$30 processing fee for international applicants.</p><ul><li>Academic transcripts and certificates</li><li>CSEC/CAPE or equivalent qualifications, or A-levels</li><li>English proficiency proof for non-native speakers</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UWI is funded by 17 contributing Caribbean countries, so tuition depends on nationality. Students from non-contributing countries pay in US dollars.</p><ul><li>MBBS for students from non-contributing countries: about US$27,000 a year for 5 years in 2026-27, plus compulsory fees</li><li>GATE funding applies only to Trinidad and Tobago citizens</li><li>A 20% fee increase was approved for St. Augustine but not for 2025-26; confirm the 2026-27 booklets</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> CSEC/CAPE or an equivalent with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof where required</li></ul>' WHERE slug = 'trinidad-and-tobago';
COMMIT;
